<article class="module-card dam-card"><h2 class="dam-title">Damodaran BI · History</h2><div class="dam-meta"><span class="dam-chip">Indústria: <?= h($industry) ?></span></div><div class="dam-chart-shell" data-dam-chart="history" data-chart-configs='<?= h((string)json_encode($chartConfigs, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) ?>'><div class="dam-chart-top"><strong>Gráfico</strong><div class="dam-chart-buttons"><button type="button" class="dam-chart-btn" data-chart-key="history">Histórico</button></div></div><div class="dam-canvas-wrap"><canvas></canvas></div></div><div class="dam-table-wrap"><table class="dam-table"><?php if(!empty($historyRows)): ?><thead><tr><?php foreach(array_keys($historyRows[0]) as $col): ?><th><?= h((string)$col) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($historyRows as $r): ?><tr><?php foreach($r as $v): ?><td><?= h((string)$v) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody><?php else: ?><tbody><tr><td>Sem dados.</td></tr></tbody><?php endif; ?></table></div></article><script>(function(){const root=document.querySelector('[data-dam-chart="history"]');if(!root||!window.Chart)return;const canvas=root.querySelector('canvas');const cfgs=JSON.parse(root.getAttribute('data-chart-configs')||'{}');new Chart(canvas.getContext('2d'),cfgs.history);root.querySelector('.dam-chart-btn')?.classList.add('is-active');})();</script>